svg.script:

var el = document.getElementById('gaussian');
var hRx = document.getElementById('handle-rx');
var hRy = document.getElementById('handle-ry');
var label = document.getElementById('size-label');
var bbox = document.getElementById('bbox');
var tightBbox = document.getElementById('tight-bbox');
var svg = el.ownerSVGElement;
var cosA = Math.cos(30 * Math.PI / 180);
var sinA = Math.sin(30 * Math.PI / 180);
var TILE = 32, GX = 80, GY = 40, TIGHT = 0.5;

function update() {
  var cx = +el.getAttribute('cx');
  var cy = +el.getAttribute('cy');
  var rx = +el.getAttribute('rx');
  var ry = +el.getAttribute('ry');

  hRx.setAttribute('cx', cx + rx * cosA);
  hRx.setAttribute('cy', cy + rx * sinA);
  hRy.setAttribute('cx', cx - ry * sinA);
  hRy.setAttribute('cy', cy + ry * cosA);
  label.textContent = 'rx=' + Math.round(rx) + '  ry=' + Math.round(ry);

  var hw = Math.sqrt(rx*rx*cosA*cosA + ry*ry*sinA*sinA);
  var hh = Math.sqrt(rx*rx*sinA*sinA + ry*ry*cosA*cosA);
  var minX = Math.floor((cx - hw - GX) / TILE) * TILE + GX;
  var minY = Math.floor((cy - hh - GY) / TILE) * TILE + GY;
  var maxX = Math.ceil((cx + hw - GX) / TILE) * TILE + GX;
  var maxY = Math.ceil((cy + hh - GY) / TILE) * TILE + GY;

  bbox.setAttribute('x', minX);
  bbox.setAttribute('y', minY);
  bbox.setAttribute('width', maxX - minX);
  bbox.setAttribute('height', maxY - minY);

  tightBbox.setAttribute('x', cx - hw * TIGHT);
  tightBbox.setAttribute('y', cy - hh * TIGHT);
  tightBbox.setAttribute('width', 2 * hw * TIGHT);
  tightBbox.setAttribute('height', 2 * hh * TIGHT);
}

update();

function mousePos(evt) {
  var pt = svg.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(svg.getScreenCTM().inverse());
}

var dragging = null, startVal, startMouse;

function onHandle(axis, e) {
  e.preventDefault(); e.stopPropagation();
  dragging = axis; startVal = +el.getAttribute(axis); startMouse = mousePos(e);
}
hRx.addEventListener('mousedown', onHandle.bind(null, 'rx'));
hRy.addEventListener('mousedown', onHandle.bind(null, 'ry'));

el.addEventListener('mousedown', function(e) {
  e.preventDefault(); e.stopPropagation();
  dragging = 'move'; startMouse = mousePos(e); el.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', function(e) {
  if (!dragging) return;
  var pos = mousePos(e);
  var dx = pos.x - startMouse.x;
  var dy = pos.y - startMouse.y;

  if (dragging === 'rx') {
    el.setAttribute('rx', Math.max(10, startVal + dx * cosA + dy * sinA));
  } else if (dragging === 'ry') {
    el.setAttribute('ry', Math.max(10, startVal - dx * sinA + dy * cosA));
  } else {
    el.setAttribute('cx', +el.getAttribute('cx') + dx);
    el.setAttribute('cy', +el.getAttribute('cy') + dy);
    el.setAttribute('transform', 'rotate(30,' + el.getAttribute('cx') + ',' + el.getAttribute('cy') + ')');
    startMouse = pos;
  }
  update();
  label.setAttribute('opacity', '1');
  label.setAttribute('x', +el.getAttribute('cx'));
  label.setAttribute('y', +el.getAttribute('cy') + +el.getAttribute('ry') + 30);
});

document.addEventListener('mouseup', function() {
  if (dragging) {
    dragging = null;
    el.style.cursor = 'move';
    setTimeout(function() { label.setAttribute('opacity', '0'); }, 1500);
  }
});
